/** All writes are to an isolated Testcontainers database; no production producer or financial sources. */
@Testcontainers
class UsReportRepositoryPostgresTest {
    @Container static final PostgreSQLContainer<?> DB=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("task542_test").withUsername("assets").withPassword("test-only");
    JdbcTemplate jdbc;DataSourceTransactionManager manager;UsReportRepository repository;UsReportPublisher publisher;UsReportCapturePort capture;
    @BeforeEach void setup()throws Exception{var ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);jdbc.execute("DROP SCHEMA public CASCADE; CREATE SCHEMA public; CREATE TABLE app_user(id bigint PRIMARY KEY,status varchar(16) NOT NULL DEFAULT 'ACTIVE');INSERT INTO app_user(id) VALUES(7),(8);CREATE TABLE asset_snapshot(id bigint PRIMARY KEY,owner_user_id bigint REFERENCES app_user(id));CREATE TABLE srpp_policy_registry(policy_bundle_sha256 char(64) PRIMARY KEY);CREATE TABLE api_error_log_operation(source varchar(16),operation_key varchar(96),operation_label varchar(96),display_order int,PRIMARY KEY(source,operation_key));CREATE FUNCTION reject_srpp_immutable_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable'; END $$;");jdbc.update("INSERT INTO srpp_policy_registry VALUES(?)",AUTHORITY.decision().policy().bundleHash());migration();repository=new UsReportRepository(jdbc);capture=mock(UsReportCapturePort.class);publisher=new UsReportPublisher(repository,capture,AUTHORITY,calendar());}
    void migration()throws Exception{jdbc.execute(new ClassPathResource("db/changelog/changes/v1.160.0-srpp-us-report-calculations.sql").getContentAsString(StandardCharsets.UTF_8));}
    void imported(long owner,String consumer,boolean armed){ObjectNode state=stateWrapper(owner,consumer,true);String policy=state.path("watchPolicySha256").asText();ObjectNode evidence=JsonNodeFactory.instance.objectNode().put("ownerUserId",owner).put("consumer",consumer).put("ledgerSha256","c".repeat(64));jdbc.update("INSERT INTO srpp_us_watch_import(owner_user_id,consumer,market,ledger_sha256,watch_policy_sha256,evidence_jcs,imported_at) VALUES(?,?,'US',?,?,?,?)",owner,consumer,"c".repeat(64),policy,SrppJcs.canonicalize(evidence),java.sql.Timestamp.from(AT.minusSeconds(60)));if(armed){JsonNode value=state.path("ledger").path("states").path("GOOGL");jdbc.update("INSERT INTO srpp_us_watch_state(owner_user_id,consumer,market,symbol,version,state_jcs,state_sha256,updated_at) VALUES(?,?,'US','GOOGL',1,?,?,?)",owner,consumer,SrppJcs.canonicalize(value),SrppJcs.hash(value),java.sql.Timestamp.from(AT.minusSeconds(60)));}}
    UsReportReadPort.Saved publish(long owner,String consumer,UsReportCapturePort.Frozen f){return new TransactionTemplate(manager).execute(tx->{repository.lockOwner(owner);return publisher.publish(scope(owner,consumer),f,repository.state(owner,consumer),f.capturedAt().plusSeconds(1));});}
    int count(String table){return jdbc.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
    @Test void coherentRehashCannotPromoteStaleAssetsOrFabricatedHistoryProvenance(){var packet=publish(7,"Claude",frozen(false));for(String attack:List.of("stale-assets","history-value","trusted-flag")){ObjectNode out=(ObjectNode)SrppJcs.parseStrict(packet.content());ObjectNode sources=(ObjectNode)out.path("inputBundle").path("sources");switch(attack){case "stale-assets"->sources.withObject("assets").put("generatedAt",AT.minusSeconds(301).toString());case "history-value"->((ObjectNode)sources.path("market").path("symbols").get(0).path("priceHistory").get(0)).put("close","9999");case "trusted-flag"->((ObjectNode)sources.path("market").path("symbols").get(0).path("priceHistory").get(0)).putNull("closeSource");}for(var entry:sources.properties()){String digest=SrppJcs.hash(entry.getValue());((ObjectNode)out.path("sourceVector").path(entry.getKey())).put("sha256",digest).put("revision",digest);}out.put("inputSnapshotSha256",SrppJcs.hash(out.path("inputBundle")));out.remove("contentSha256");out.put("contentSha256",SrppJcs.hash(out));assertThatThrownBy(()->UsReportEnvelopeValidator.validate(SrppJcs.canonicalize(out))).as(attack).isInstanceOf(UsReportProblem.class);}}
    @Test void realMigrationSqlGeneratorRechecksDatabaseOwnerAndActiveAccountAndIsInsertOnly()throws Exception{
        jdbc.update("INSERT INTO asset_snapshot(id,owner_user_id) VALUES(17,7)");String watch=UsCoreSellCalculator.watchPolicyFingerprint(AUTHORITY.model().path("execution_policy").path("core_sell_guard_d174"));ObjectNode evidence=JsonNodeFactory.instance.objectNode().put("ownerUserId",8).put("consumer","Codex").put("snapshotId",17).put("ledgerSha256","c".repeat(64)).put("watchPolicySha256",watch);
        assertThatThrownBy(()->jdbc.execute(migrationSql(evidence))).isInstanceOf(RuntimeException.class);assertThat(count("srpp_us_watch_import")).isZero();evidence.put("ownerUserId",7);String sql=migrationSql(evidence);jdbc.execute(sql);jdbc.execute(sql);assertThat(count("srpp_us_watch_import")).isEqualTo(1);assertThat(count("srpp_us_watch_state")).isZero();jdbc.update("UPDATE app_user SET status='INACTIVE' WHERE id=7");assertThatThrownBy(()->jdbc.execute(sql)).isInstanceOf(RuntimeException.class);assertThat(count("srpp_us_watch_import")).isEqualTo(1);jdbc.update("UPDATE app_user SET status='ACTIVE' WHERE id=7");evidence.put("ledgerSha256","d".repeat(64));assertThatThrownBy(()->jdbc.execute(migrationSql(evidence))).isInstanceOf(RuntimeException.class);assertThat(jdbc.queryForObject("SELECT ledger_sha256 FROM srpp_us_watch_import",String.class)).isEqualTo("c".repeat(64));
    }
    private static String migrationSql(ObjectNode evidence)throws Exception{
        Path folder=Path.of(System.getProperty("user.dir")).toAbsolutePath();Path script=folder.resolve("scripts/validate-us-watch-migration.py");if(!Files.exists(script))script=folder.getParent().resolve("scripts/validate-us-watch-migration.py");
        String python="import importlib.util,json,sys;spec=importlib.util.spec_from_file_location('migration',sys.argv[1]);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);print(m.registration_sql(json.load(sys.stdin),{}))";
        Process process=new ProcessBuilder("python3","-B","-c",python,script.toString()).start();process.getOutputStream().write(SrppJcs.canonicalize(evidence).getBytes(StandardCharsets.UTF_8));process.getOutputStream().close();String sql=new String(process.getInputStream().readAllBytes(),StandardCharsets.UTF_8),error=new String(process.getErrorStream().readAllBytes(),StandardCharsets.UTF_8);assertThat(process.waitFor()).as(error).isZero();return sql;
    }
    @Test void verifiedImportIsARealSourceChangeEvenWhenPricesAndTransportAreIdentical(){var f=frozen(false);var unavailable=publish(7,"Codex",f);assertThat(SrppJcs.parseStrict(unavailable.content()).path("modules").get(0).path("coverage").asText()).isEqualTo("UNAVAILABLE");imported(7,"Codex",false);var imported=publish(7,"Codex",f);assertThat(imported.id()).isNotEqualTo(unavailable.id());assertThat(imported.sourceHash()).isNotEqualTo(unavailable.sourceHash());assertThat(SrppJcs.parseStrict(imported.content()).path("modules").get(0).path("coverage").asText()).isEqualTo("COMPLETE");assertThat(repository.byId(7,unavailable.id()).orElseThrow().content()).isEqualTo(unavailable.content());assertThat(publish(7,"Codex",f).id()).isEqualTo(imported.id());assertThat(count("srpp_us_report_package")).isEqualTo(2);}
    @Test void readTransportClocksAreIdempotentButChangedCanonicalPricePublishesNewImmutableRevision(){
        imported(7,"Codex",true);var first=publish(7,"Codex",frozen(false));var later=frozen(false);Instant newer=AT.plusSeconds(60);later.sources().withObject("assets").put("generatedAt",newer.toString());later.sources().withObject("market").withObject("radarList").put("generatedAt",newer.toString());for(JsonNode row:later.sources().path("market").path("symbols"))((ObjectNode)row.path("radar")).put("generatedAt",newer.toString());later.sources().withObject("us-tactical").put("asof",newer.toString());for(String key:new ArrayList<>(UsReportEnvelopeValidator.names(later.sources())))UsReportCaptureAdapter.source(later.sources(),later.sourceVector(),key,later.sources().path(key),newer,later.sourceVector().path(key).path("coverage").asText(),later.sourceVector().path(key).path("validation").asText());
        var second=publish(7,"Codex",new UsReportCapturePort.Frozen(later.sources(),later.sourceVector(),newer));assertThat(second.id()).isEqualTo(first.id());assertThat(count("srpp_us_watch_transition")).isEqualTo(1);
        ((ObjectNode)later.sources().path("market").path("symbols").get(0).path("quote")).put("price",98.4);UsReportCaptureAdapter.source(later.sources(),later.sourceVector(),"market",later.sources().path("market"),newer,"COMPLETE","VERIFIED");var changed=publish(7,"Codex",new UsReportCapturePort.Frozen(later.sources(),later.sourceVector(),newer));assertThat(changed.id()).isNotEqualTo(first.id());assertThat(repository.byId(7,first.id()).orElseThrow().content()).isEqualTo(first.content());assertThat(count("srpp_us_report_package")).isEqualTo(2);assertThat(count("srpp_us_watch_transition")).isEqualTo(2);
    }
    @Test void eightConcurrentIdenticalCapturesPublishAndAdvanceOnlyOnce()throws Exception{imported(7,"Codex",true);var f=frozen(false);ExecutorService pool=Executors.newFixedThreadPool(8);CountDownLatch ready=new CountDownLatch(8),go=new CountDownLatch(1);List<Future<UsReportReadPort.Saved>> tasks=new ArrayList<>();for(int i=0;i<8;i++)tasks.add(pool.submit(()->{ready.countDown();go.await();return publish(7,"Codex",f);}));assertThat(ready.await(10,TimeUnit.SECONDS)).isTrue();go.countDown();Set<UUID> ids=new HashSet<>();try{for(var task:tasks)ids.add(task.get(30,TimeUnit.SECONDS).id());}finally{pool.shutdownNow();pool.awaitTermination(10,TimeUnit.SECONDS);}assertThat(ids).hasSize(1);assertThat(count("srpp_us_report_package")).isEqualTo(1);assertThat(count("srpp_us_watch_transition")).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT version FROM srpp_us_watch_state",Long.class)).isEqualTo(2L);}
    @Test void coreReadyPackageKeepsOriginalBytesAndStateAuditAcrossMigrationReplay()throws Exception{imported(7,"Codex",true);var first=publish(7,"Codex",frozen(false));JsonNode out=UsReportEnvelopeValidator.validate(first.content());assertThat(out.path("modules").get(0).path("data").path("results").get(0).path("status").asText()).isEqualTo("CORE_SELL_READY");assertThat(out.path("tradeAuthorization").asBoolean()).isFalse();migration();assertThat(repository.byId(7,first.id()).orElseThrow().content()).isEqualTo(first.content());assertThatThrownBy(()->jdbc.update("UPDATE srpp_us_report_package SET content_jcs='{}' WHERE id=?",first.id())).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->jdbc.update("DELETE FROM srpp_us_watch_transition")).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->jdbc.update("DELETE FROM srpp_us_watch_import")).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->jdbc.update("UPDATE srpp_us_watch_state SET version=version+2")).isInstanceOf(RuntimeException.class);assertThat(count("api_error_log_operation")).isEqualTo(1);Files.writeString(Path.of("/private/tmp/task542-us-report-synthetic.json"),first.content());Files.writeString(Path.of("/private/tmp/task542-us-assets-synthetic.json"),assets().toString());}
    @Test void failureRollsBackPackageTransitionAndStateTogether(){imported(7,"Codex",true);assertThatThrownBy(()->new TransactionTemplate(manager).execute(tx->{repository.lockOwner(7);publisher.publish(scope(7,"Codex"),frozen(false),repository.state(7,"Codex"),AT.plusSeconds(1));throw new IllegalStateException("injected failure after publication");})).isInstanceOf(IllegalStateException.class);assertThat(count("srpp_us_report_package")).isZero();assertThat(count("srpp_us_watch_transition")).isZero();assertThat(jdbc.queryForObject("SELECT version FROM srpp_us_watch_state",Long.class)).isEqualTo(1L);}
    @Test void missingConsumerLedgerCannotBorrowOtherTrackOrBecomeComplete(){imported(7,"Codex",true);var result=publish(7,"Claude",frozen(false));JsonNode core=UsReportEnvelopeValidator.validate(result.content()).path("modules").get(0);assertThat(core.path("coverage").asText()).isEqualTo("UNAVAILABLE");assertThat(core.path("data").path("stateBefore").isNull()).isTrue();assertThat(core.path("data").path("stateAfter").isNull()).isTrue();assertThat(count("srpp_us_watch_state")).isEqualTo(1);assertThat(count("srpp_us_watch_transition")).isZero();assertThat(repository.byId(8,result.id())).isEmpty();}
    @Test void badUniverseCannotMasqueradeAsNoCandidatesComplete(){imported(7,"Codex",false);var f=frozen(true);f.sources().withObject("market").putArray("symbols");for(String key:List.of("holdingSymbols","radarSymbols","watchSymbols","symbols"))f.sources().withObject("universe").putArray(key);f.sources().putNull("assets");UsReportCaptureAdapter.source(f.sources(),f.sourceVector(),"assets",f.sources().path("assets"),AT,"NONE","UNAVAILABLE");UsReportCaptureAdapter.source(f.sources(),f.sourceVector(),"universe",f.sources().path("universe"),AT,"PARTIAL","UNAVAILABLE");f.sources().withObject("market").putNull("radarList");UsReportCaptureAdapter.source(f.sources(),f.sourceVector(),"market",f.sources().path("market"),AT,"PARTIAL","UNAVAILABLE");var result=publish(7,"Codex",f);JsonNode core=UsReportEnvelopeValidator.validate(result.content()).path("modules").get(0);assertThat(core.path("coverage").asText()).isEqualTo("UNAVAILABLE");assertThat(core.path("reasonCodes")).contains(JsonNodeFactory.instance.textNode("US_RADAR_LIST_SOURCE_UNAVAILABLE"));}
    @Test void getHasZeroMutationAndFixedRunOutsideWindowIsOnlyDiagnostic(){imported(7,"Codex",true);var result=publish(7,"Codex",frozen(false));var owner=mock(CurrentUserContext.class);when(owner.hasUser()).thenReturn(true);when(owner.getStatus()).thenReturn("ACTIVE");when(owner.getEffectiveUserId()).thenReturn(7L);var registry=mock(SrppPolicyRegistryService.class);when(registry.find(scope(7,"Codex").policy())).thenReturn(Optional.of(SrppReportFixtures.supported()));var swagger=mock(PublishedSwaggerIdentity.class);when(swagger.sha256()).thenReturn(Optional.of(SWAGGER));var service=new UsReportReadService(owner,calendar(),registry,swagger,AUTHORITY,repository,Clock.fixed(AT.plusSeconds(5*3600),ZoneOffset.UTC));var q=UsReportRequestTest.query();assertThatThrownBy(()->service.read(q)).isInstanceOfSatisfying(UsReportProblem.class,p->assertThat(p.code()).isEqualTo("OUTSIDE_REPORT_WINDOW"));q.add("calculationRunId",result.id().toString());long stateVersion=jdbc.queryForObject("SELECT version FROM srpp_us_watch_state",Long.class);TransactionTemplate read=new TransactionTemplate(manager);read.setReadOnly(true);for(int i=0;i<3;i++)assertThat((String)read.execute(tx->service.read(q))).isEqualTo(result.content());verifyNoInteractions(capture);assertThat(count("srpp_us_report_package")).isEqualTo(1);assertThat(count("srpp_us_watch_transition")).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT version FROM srpp_us_watch_state",Long.class)).isEqualTo(stateVersion);q.set("consumer","Claude");assertThatThrownBy(()->service.read(q)).isInstanceOfSatisfying(UsReportProblem.class,p->assertThat(p.code()).isEqualTo("CONTEXT_IDENTITY_MISMATCH"));when(owner.getEffectiveUserId()).thenReturn(8L);assertThatThrownBy(()->service.read(q)).isInstanceOfSatisfying(UsReportProblem.class,p->assertThat(p.code()).isEqualTo("CALCULATION_NOT_FOUND"));}
    @Test void contentSourceInputAndFlagOnlyCompleteTamperingAreRejected(){imported(7,"Codex",true);var result=publish(7,"Claude",frozen(false));for(String mutation:List.of("content","source","input","complete")){ObjectNode out=(ObjectNode)SrppJcs.parseStrict(result.content());switch(mutation){case "content"->out.put("placesOrders",true);case "source"->((ObjectNode)out.path("sourceVector").path("assets")).put("sha256","0".repeat(64));case "input"->((ObjectNode)out.path("inputBundle")).put("ownerUserId",8);case "complete"->{ObjectNode module=(ObjectNode)out.path("modules").get(0);module.put("coverage","COMPLETE");((ObjectNode)module.path("data")).put("coverage","COMPLETE");}}out.remove("contentSha256");out.put("contentSha256",SrppJcs.hash(out));assertThatThrownBy(()->UsReportEnvelopeValidator.validate(SrppJcs.canonicalize(out))).as(mutation).isInstanceOf(UsReportProblem.class);}}
}
